            s:AddGroup({ Source = gradient("Skeleton", "Skeleton") })
                :AddSlider({ Label = "Thickness", Min = 1, Max = 6, Config = Q("Skeleton", "Thickness") })
            local hm = s:AddGroup({ Source = color("Head Marker", "HeadMarker", true) })
