-- Nuclear hide helper (same as v3)
_G.__QuantumKpLoading = true
do
    local coreGuiService = (gethui and gethui()) or game:GetService("CoreGui")
    _G.__QuantumPreKpGuis = {}
    for _, child in ipairs(coreGuiService:GetChildren()) do
        _G.__QuantumPreKpGuis[child] = true
    end
    coreGuiService.ChildAdded:Connect(function(child)
        if not _G.__QuantumKpLoading then return end
        if child:IsA("ScreenGui") and not _G.__QuantumPreKpGuis[child] then
            pcall(function()
                child.Name = "QuantumKillMe_" .. child.Name
                child.Enabled = false
            end)
        end
    end)
end

local function waitForQuantumStore(timeout)
    local t0 = os.clock()
    while not _G.__QuantumStore do
        if os.clock() - t0 > (timeout or 15) then return nil end
        task.wait(0.1)
    end
    return _G.__QuantumStore
end

task.spawn(function()
    local Store = waitForQuantumStore(15)
    _G.__QuantumKpLoading = false

    task.spawn(function()
        local coreGui = (gethui and gethui()) or game:GetService("CoreGui")
        while task.wait(0.5) do
            for _, child in ipairs(coreGui:GetChildren()) do
                if not child:IsA("ScreenGui") then continue end
                if child.Name:sub(1, 14) == "QuantumKillMe_" and child.Enabled then
                    pcall(function() child.Enabled = false end)
                end
            end
        end
    end)

    if not Store then
        warn("[Quantum] QuantumStore not found - skipping Quantum UI (Quantum native UI still works)")
        return
    end
    pcall(function() if Library.Notify then Library:Notify("Quantum loading...", 3) end end)

    -- ------------------------------------------------------------------
    -- Store helpers with retry
    -- ------------------------------------------------------------------
    local function safeGet(path)
        local ok, v = pcall(function() return Store:Get(path) end)
        return ok and v or nil
    end
    local function safeSet(path, v)
        pcall(function() Store:Set(path, v) end)
    end
    local function safeChanged(path, fn)
        pcall(function()
            local sig = Store:Changed(path)
            if sig and sig.Connect then
                sig:Connect(fn)
            end
        end)
    end

    -- ------------------------------------------------------------------
    -- Window
    -- ------------------------------------------------------------------
    local Window = Library:CreateWindow({
        Title = "Quantum",
        Center = true, AutoShow = true, TabPadding = 8, MenuFadeTime = 0.2,
    })

    -- ------------------------------------------------------------------
    -- Improved bridge helpers v2
    -- ------------------------------------------------------------------
    -- Track skipped bindings so we can diagnose UI gaps.
    _G.__QuantumSkipped = _G.__QuantumSkipped or {}

    local function bindToggle(group, flag, label, path, extra)
        extra = extra or {}
        return pcall(function()
            local def = safeGet(path)
            -- If the path doesn't exist in KH's data model, auto-generated
            -- features.json made a wrong path (e.g. {"Chams","Enabled"} when
            -- real structure is {"Chams","Character","Enabled"}). Skip these
            -- so users don't see non-functional toggles.
            if def == nil then
                table.insert(_G.__QuantumSkipped, "Toggle " .. table.concat(path, "."))
                return
            end
            if type(def) ~= "boolean" then
                def = extra.default or false
            end
            -- Force OFF only the top-level master toggles ({Section, "Enabled"}).
            if #path == 2 and path[2] == "Enabled" then
                safeSet(path, false)
                def = false
            end
            local t = group:AddToggle(flag, {
                Text = label, Default = def,
                Tooltip = extra.tooltip,
            })
            if t and t.OnChanged then
                t:OnChanged(function(v) safeSet(path, v) end)
            end
            -- Backend sync
            safeChanged(path, function(v)
                if Toggles[flag] and Toggles[flag].Value ~= v then
                    pcall(function() Toggles[flag]:SetValue(v) end)
                end
            end)
            return t
        end)
    end

    local function bindSlider(group, flag, label, mn, mx, rounding, path, extra)
        extra = extra or {}
        return pcall(function()
            local def = safeGet(path)
            if def == nil then table.insert(_G.__QuantumSkipped, path[1] .. "." .. (path[2] or "")) return end
            if type(def) ~= "number" then def = extra.default or mn end
            def = math.max(mn, math.min(mx, def))
            local s = group:AddSlider(flag, {
                Text = label, Default = def, Min = mn, Max = mx,
                Rounding = rounding, Suffix = extra.suffix or "",
            })
            if s and s.OnChanged then
                s:OnChanged(function(v) safeSet(path, v) end)
            end
            safeChanged(path, function(v)
                if Options[flag] and Options[flag].Value ~= v then
                    pcall(function() Options[flag]:SetValue(v) end)
                end
            end)
            return s
        end)
    end

    -- RangeSlider via TWO sliders (Min / Max)
    local function bindRangeSlider(group, flag, label, mn, mx, path)
        return pcall(function()
            local def = safeGet(path)
            if def == nil then table.insert(_G.__QuantumSkipped, path[1] .. "." .. (path[2] or "")) return end
            local defMin, defMax = mn, mx
            if type(def) == "table" then
                defMin = tonumber(def.Min) or mn
                defMax = tonumber(def.Max) or mx
            end
            local sMin = group:AddSlider(flag .. "_min", {
                Text = label .. " Min", Default = defMin, Min = mn, Max = mx, Rounding = 1,
            })
            local sMax = group:AddSlider(flag .. "_max", {
                Text = label .. " Max", Default = defMax, Min = mn, Max = mx, Rounding = 1,
            })
            local function push()
                local lo = Options[flag .. "_min"] and Options[flag .. "_min"].Value or defMin
                local hi = Options[flag .. "_max"] and Options[flag .. "_max"].Value or defMax
                if lo > hi then lo, hi = hi, lo end
                safeSet(path, { Min = lo, Max = hi })
            end
            if sMin and sMin.OnChanged then sMin:OnChanged(push) end
            if sMax and sMax.OnChanged then sMax:OnChanged(push) end
        end)
    end

    -- Dropdown with proper multi handling (both array and map formats attempted)
    local function bindDropdown(group, flag, label, options, multi, path, extra)
        extra = extra or {}
        return pcall(function()
            if not options or #options == 0 then options = { "None" } end
            local def = safeGet(path)
            if def == nil then table.insert(_G.__QuantumSkipped, path[1] .. "." .. (path[2] or "")) return end
            if multi then
                local defTable = {}
                if type(def) == "table" then
                    -- Try both formats
                    for k, v in pairs(def) do
                        if type(k) == "string" and v then defTable[k] = true
                        elseif type(k) == "number" and type(v) == "string" then defTable[v] = true end
                    end
                end
                local d = group:AddDropdown(flag, {
                    Values = options, Default = 1, Multi = true,
                    Text = label, AllowNull = true,
                    Tooltip = extra.tooltip,
                })
                if d and d.SetValue then
                    pcall(function() d:SetValue(defTable) end)
                end
                if d and d.OnChanged then
                    d:OnChanged(function(v)
                        -- Try array format first (most Quantum features expect this)
                        local arr = {}
                        if type(v) == "table" then
                            for k, en in pairs(v) do if en then arr[#arr+1] = k end end
                        end
                        safeSet(path, arr)
                    end)
                end
                return d
            else
                local defIdx = 1
                if type(def) == "string" then
                    for i, o in ipairs(options) do if o == def then defIdx = i; break end end
                end
                local d = group:AddDropdown(flag, {
                    Values = options, Default = defIdx, Multi = false, Text = label,
                    Tooltip = extra.tooltip,
                })
                if d and d.OnChanged then
                    d:OnChanged(function(v) safeSet(path, v) end)
                end
                safeChanged(path, function(v)
                    if Options[flag] and Options[flag].Value ~= v then
                        pcall(function() Options[flag]:SetValue(v) end)
                    end
                end)
                return d
            end
        end)
    end

    -- Color: use AddLabel.AddColorPicker chaining (Linoria/Obsidian pattern)
    local function bindColor(group, flag, label, path)
        return pcall(function()
            local def = safeGet(path)
            if def == nil then table.insert(_G.__QuantumSkipped, path[1] .. "." .. (path[2] or "")) return end
            local defC
            if typeof(def) == "Color3" then defC = def
            elseif type(def) == "table" and def.R then defC = Color3.fromRGB(def.R*255, def.G*255, def.B*255)
            else defC = Color3.fromRGB(185, 131, 255) end
            -- Pattern 1: Groupbox.AddLabel().AddColorPicker()
            local lbl = group:AddLabel(label)
            if lbl and lbl.AddColorPicker then
                local c = lbl:AddColorPicker(flag, { Default = defC, Title = label })
                if c and c.OnChanged then
                    c:OnChanged(function()
                        local col = Options[flag] and Options[flag].Value
                        if col then safeSet(path, col) end
                    end)
                end
                return
            end
            -- Pattern 2: Direct on groupbox
            if group.AddColorPicker then
                local c = group:AddColorPicker(flag, { Default = defC, Title = label })
                if c and c.OnChanged then
                    c:OnChanged(function()
                        local col = Options[flag] and Options[flag].Value
                        if col then safeSet(path, col) end
                    end)
                end
            end
        end)
    end

    local function bindInput(group, flag, label, path, extra)
        extra = extra or {}
        return pcall(function()
            local def = safeGet(path)
            if type(def) ~= "string" then def = tostring(def or "") end
            local i = group:AddInput(flag, {
                Default = def, Numeric = extra.numeric or false, Text = label,
                Placeholder = extra.placeholder or "", Finished = true,
            })
            if i and i.OnChanged then
                i:OnChanged(function(v) safeSet(path, v) end)
            end
        end)
    end

    local function bindKeybind(group, flag, label, path)
        return pcall(function()
            local def = safeGet(path)
            local defKey = "None"
            if type(def) == "table" then defKey = def.Key or "None" end
            local kb = group:AddKeyPicker(flag, {
                Default = defKey, Text = label, Mode = "Toggle",
                SyncToggleState = false, NoUI = false,
            })
            if kb and kb.OnChanged then
                kb:OnChanged(function()
                    local v = Options[flag] and Options[flag].Value
                    safeSet(path, { Key = v or "None", Mode = "Toggle" })
                end)
            end
        end)
    end

    -- Dynamic dropdown - re-fetch options later via Store or callback
    local function bindDropdownDynamic(group, flag, label, options_fn, multi, path)
        return pcall(function()
            local options
            do
                local ok, result = pcall(options_fn)
                options = (ok and type(result) == "table" and result) or {}
            end
            if #options == 0 then options = { "None" } end
            bindDropdown(group, flag, label, options, multi, path)
            -- Refresh options every 5s (fully pcall-wrapped - Options global can
            -- be unavailable in some scopes/timings; silently skip when so).
            task.spawn(function()
                while task.wait(5) do
                    pcall(function()
                        local ok, new_opts = pcall(options_fn)
                        if not ok or type(new_opts) ~= "table" or #new_opts == 0 then return end
                        local opts = rawget(getfenv(0), "Options")
                                  or (getgenv and getgenv().Options)
                                  or rawget(_G, "Options")
                        if type(opts) ~= "table" then return end
                        local widget = opts[flag]
                        if type(widget) ~= "table" or type(widget.SetValues) ~= "function" then return end
                        widget:SetValues(new_opts)
                    end)
                end
            end)
        end)
    end

    -- Group with visibility source: hide children when source toggle is off
    local function withSource(group, source_path, build_fn)
        local function run()
            -- Create widgets - this is a simple "always visible" approach since
            -- we can't natively hide child widgets in Obsidian. We rely on backend
            -- to not react when source is off.
            build_fn(group)
        end
        run()
    end


