local CFG = {
    VOID_DISTANCE = 1,
    SET_X = 10000000,
    SET_Y = 0,
    SET_Z = 10000000,
    METHOD = "Static",
    MOVEMENT_PATTERN = "None",
    MOVEMENT_SPEED = 10,
    EFFECT_RADIUS = 10000,
}

