--==================================================
-- VOID ENGINE
--==================================================
local function getRanges()
    local pct = math.clamp(CFG.VOID_DISTANCE, 0, 1)
    return
        math.clamp(math.abs(CFG.SET_X) * pct, 0, 10000000),
        math.clamp(math.abs(CFG.SET_Y) * pct, 0, 10000000),
        math.clamp(math.abs(CFG.SET_Z) * pct, 0, 10000000)
end

local function stepOffset()
    local method = CFG.METHOD
    local xMax, yMax, zMax = getRanges()
    local ox, oy, oz = 0, 0, 0

    if method == "Fixed" then
        ox = CFG.SET_X * CFG.VOID_DISTANCE
        oy = CFG.SET_Y * CFG.VOID_DISTANCE
        oz = CFG.SET_Z * CFG.VOID_DISTANCE
    elseif method == "Endpoints" then
        ox = (math.random(0, 1) == 1 and 1 or -1) * xMax
        oy = (yMax > 0) and ((math.random(0, 1) == 1 and 1 or -1) * yMax) or 0
        oz = (math.random(0, 1) == 1 and 1 or -1) * zMax
    elseif method == "Static" or method == "Random" or method == "Chaos" then
        ox = (math.random() * 2 - 1) * xMax
        oy = (math.random() * 2 - 1) * yMax
        oz = (math.random() * 2 - 1) * zMax
    elseif method == "Quantum" then
        local s = math.random(0, 1) == 1 and 1 or -1
        ox = s * xMax * (0.7 + math.random() * 0.3)
        oy = (math.random() * 2 - 1) * yMax
        oz = s * zMax * (0.7 + math.random() * 0.3)
    elseif method == "Drift" then
        local t = elapsed
        ox = math.noise(t * 0.2, 1.1) * 2 * xMax
        oy = math.noise(2.2, t * 0.15) * 2 * yMax
        oz = math.noise(t * 0.18, t * 0.12) * 2 * zMax
    elseif method == "Loop" then
        local r = math.max(xMax, zMax)
        ox = math.cos(elapsed * 3) * r
        oy = math.sin(elapsed * 1.5) * yMax
        oz = math.sin(elapsed * 3) * r
    elseif method == "Spiral" then
        local r = math.max(xMax, zMax) * (0.25 + 0.75 * math.abs(math.sin(elapsed * 0.5)))
        ox = math.cos(elapsed * 4) * r
        oy = math.sin(elapsed * 0.8) * yMax
        oz = math.sin(elapsed * 4) * r
    else
        ox = (math.random() * 2 - 1) * xMax
        oy = (math.random() * 2 - 1) * yMax
        oz = (math.random() * 2 - 1) * zMax
    end

    local base = originalPos or Vector3.zero
    return Vector3.new(base.X + ox, base.Y + oy, base.Z + oz)
end

local function applyMotion(pos)
    local pattern = CFG.MOVEMENT_PATTERN
    if pattern == "None" then return pos end

    local spd = math.max(CFG.MOVEMENT_SPEED, 1)
    local rad = math.clamp(CFG.EFFECT_RADIUS, 0, 214748364)

    if pattern == "Spin" then
        local a = elapsed * (spd * 0.08)
        local r = math.min(rad, 100000)
        return pos + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)
    elseif pattern == "Orbit" then
        local a = elapsed * (spd * 0.05)
        local r = math.min(rad, 200000)
        return pos + Vector3.new(math.cos(a) * r, math.sin(a * 0.4) * r * 0.2, math.sin(a) * r)
    elseif pattern == "Random" then
        local r = math.min(rad, 300000)
        return pos + Vector3.new((math.random() - 0.5) * r, (math.random() - 0.5) * r * 0.4, (math.random() - 0.5) * r)
    elseif pattern == "Desync" then
        local a = elapsed * (spd * 0.12)
        local r = math.min(rad, 250000)
        return pos + Vector3.new(math.sin(a) * r, math.cos(a * 1.4) * r * 0.35, math.sin(a * 0.6) * r)
    elseif pattern == "Erratic" then
        local r = math.min(rad * 1.5, 500000)
        return pos + Vector3.new((math.random() - 0.5) * r, (math.random() - 0.5) * r * 0.5, (math.random() - 0.5) * r)
    end
    return pos
end

local function voidStep(dt)
    if not voidEnabled then return end
    local hrp = getRoot()
    if not hrp then return end
    if not originalPos then originalPos = hrp.Position end

    elapsed = elapsed + dt
    local target = applyMotion(stepOffset())

    hrp.CFrame = CFrame.new(target)
    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.AssemblyAngularVelocity = Vector3.zero
end

function startVoid()
    killConn("void")
    local hrp = getRoot()
    if hrp then originalPos = hrp.Position end
    elapsed = 0
    conns.void = RunService.Heartbeat:Connect(function(dt)
        if not voidEnabled then killConn("void"); return end
        voidStep(dt)
    end)
end

function stopVoid()
    killConn("void")
    local hrp = getRoot()
    if hrp and originalPos then
        hrp.CFrame = CFrame.new(originalPos)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end
    originalPos = nil
end

