--==================================================
-- RIOT ABUSER (matches screenshot)
--==================================================
local riotCFG = {
    DISTANCE_BEHIND = 10,
    HEIGHT_OFFSET = 0,
    UPDATE_RATE = 0.5,
}
local riotTarget = nil
local riotLastUpdate = 0

local function getClosestEnemy()
    local hrp = getRoot()
    if not hrp then return nil end
    local best, bestDist = nil, math.huge
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer and plr.Character then
            local thrp = plr.Character:FindFirstChild("HumanoidRootPart")
            local thum = plr.Character:FindFirstChildOfClass("Humanoid")
            if thrp and thum and thum.Health > 0 then
                local d = (hrp.Position - thrp.Position).Magnitude
                if d < bestDist then
                    bestDist = d
                    best = plr
                end
            end
        end
    end
    return best
end

local function riotStep()
    if not riotEnabled then return end
    local hrp = getRoot()
    if not hrp then return end

    -- Always refresh target on rate
    local now = tick()
    if (now - riotLastUpdate) >= riotCFG.UPDATE_RATE or not riotTarget or not riotTarget.Parent then
        riotTarget = getClosestEnemy()
        riotLastUpdate = now
    end

    if not riotTarget then return end
    local tchar = riotTarget.Character
    if not tchar then return end
    local thrp = tchar:FindFirstChild("HumanoidRootPart")
    local thum = tchar:FindFirstChildOfClass("Humanoid")
    if not thrp or not thum or thum.Health <= 0 then
        riotTarget = nil
        return
    end

    -- Teleport directly behind target every frame (same feel as original Banware)
    local look = thrp.CFrame.LookVector
    local behind = Vector3.new(-look.X, 0, -look.Z)
    if behind.Magnitude < 0.05 then
        behind = Vector3.new(0, 0, -1)
    else
        behind = behind.Unit
    end

    local targetPos = thrp.Position + behind * riotCFG.DISTANCE_BEHIND + Vector3.new(0, riotCFG.HEIGHT_OFFSET, 0)

    -- Snap teleport
    hrp.CFrame = CFrame.new(targetPos, thrp.Position)
    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.AssemblyAngularVelocity = Vector3.zero
    hrp.Velocity = Vector3.zero

    if hum then
        hum.WalkSpeed = 0
        hum.JumpPower = 0
        hum.JumpHeight = 0
    end
end

function startRiot()
    killConn("riot")
    riotLastUpdate = 0
    riotTarget = nil
    conns.riot = RunService.RenderStepped:Connect(function()
        if not riotEnabled then
            killConn("riot")
            if hum then hum.WalkSpeed = 16 end
            return
        end
        if voidEnabled then return end
        riotStep()
    end)
end

function stopRiot()
    killConn("riot")
    riotTarget = nil
    if hum then
        hum.WalkSpeed = 16
        hum.JumpPower = 50
        hum.JumpHeight = 7.2
    end
end

