--==================================================
-- SOUND EFFECTS — continuous loop + custom Keyboard/Space
--==================================================
local soundCFG = {
    ENABLED_NAME = "Keyboard",
    VOLUME = 1,
}

local KEYBOARD_B64 = [[]]
local SPACE_B64 = [[]]
local DISABLE_B64 = [[]]
local DISABLE_PATH = "Banware/void_disable.mp3"
local KEYBOARD_PATH = "Banware/keyboard.mp3"
local SPACE_PATH = "Banware/space.mp3"

local function b64decode(data)
    if crypt and crypt.base64decode then
        local ok, out = pcall(crypt.base64decode, data)
        if ok and out then return out end
    end
    local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    data = data:gsub('[^'..b..'=]', '')
    return (data:gsub('.', function(x)
        if x == '=' then return '' end
        local r, f = '', (b:find(x) - 1)
        for i = 6, 1, -1 do
            r = r .. (f % 2^i - f % 2^(i-1) > 0 and '1' or '0')
        end
        return r
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
        if #x ~= 8 then return '' end
        local c = 0
        for i = 1, 8 do
            c = c + (x:sub(i, i) == '1' and 2^(8 - i) or 0)
        end
        return string.char(c)
    end))
end

local function ensureAsset(path, b64)
    if not writefile then return nil end
    pcall(function()
        if makefolder and not isfolder("Banware") then makefolder("Banware") end
    end)
    if not (isfile and isfile(path)) then
        local data = b64decode(b64)
        if data then pcall(writefile, path, data) end
    end
    if getcustomasset and isfile and isfile(path) then
        local ok, asset = pcall(getcustomasset, path)
        if ok and asset then return asset end
    end
    return nil
end

local KEYBOARD_ASSET, SPACE_ASSET = nil, nil
local DISABLE_ASSET = nil
task.spawn(function()
    KEYBOARD_ASSET = ensureAsset(KEYBOARD_PATH, KEYBOARD_B64)
    SPACE_ASSET = ensureAsset(SPACE_PATH, SPACE_B64)
    DISABLE_ASSET = ensureAsset(DISABLE_PATH, DISABLE_B64)
end)

local SOUND_IDS = {
    None = nil,
    Keyboard = "custom:keyboard",
    Space = "custom:space",
    Whoosh = "rbxasset://sounds/impact_water.mp3",
    Glitch = "rbxasset://sounds/electronicpingshort.wav",
    Ambient = "rbxasset://sounds/background_music_loop.mp3",
    Bass = "rbxasset://sounds/swoosh.wav",
    Pulse = "rbxasset://sounds/switch.wav",
    Static = "rbxasset://sounds/collision.wav",
    Distortion = "rbxasset://sounds/action_footsteps_plastic.mp3",
    Rocket = "rbxassetid://12222216",
    Laser = "rbxassetid://137147059",
    Drone = "rbxasset://sounds/action_falling.mp3",
    Rush = "rbxasset://sounds/impact_water.mp3",
    Hum = "rbxasset://sounds/swoosh.wav",
}

local SoundService = game:GetService("SoundService")
local activeSounds = {}
local soundLoopConn = nil
local soundKeepAlive = false
local soundGeneration = 0 -- increments on every stop/start to kill stale tests

local function wipeAllBanwareSounds()
    for _, s in ipairs(activeSounds) do
        pcall(function()
            s.Looped = false
            s.Volume = 0
            s:Stop()
            s.SoundId = ""
            s:Destroy()
        end)
    end
    table.clear(activeSounds)

    local function killSound(child)
        pcall(function()
            child.Looped = false
            child.Volume = 0
            child:Stop()
            child.SoundId = ""
            child:Destroy()
        end)
    end

    local function sweep(container)
        if not container then return end
        for _, child in ipairs(container:GetDescendants()) do
            if child:IsA("Sound") then
                local n = child.Name
                if n == "BanwareSFX" or n == "BanwareVoidSFX" or n == "BanwareSpaceSound" then
                    killSound(child)
                end
            end
        end
        -- wipe folder of sounds entirely
        local folder = container:FindFirstChild("BanwareSounds")
        if folder then
            for _, child in ipairs(folder:GetChildren()) do
                if child:IsA("Sound") then killSound(child) end
            end
        end
    end

    sweep(SoundService)
    sweep(LocalPlayer:FindFirstChild("PlayerGui"))
    sweep(LocalPlayer.Character)
    local cam = workspace.CurrentCamera
    if cam then sweep(cam) end
end

local function clearSounds()
    soundKeepAlive = false
    soundGeneration = soundGeneration + 1
    if soundLoopConn then
        pcall(function() soundLoopConn:Disconnect() end)
        soundLoopConn = nil
    end
    wipeAllBanwareSounds()
    -- second pass next frame (PlayLocalSound copies can lag)
    task.defer(wipeAllBanwareSounds)
    task.delay(0.1, wipeAllBanwareSounds)
    task.delay(0.3, wipeAllBanwareSounds)
end

local function resolveSoundId(name)
    local id = SOUND_IDS[name]
    if id == "custom:keyboard" then
        if not KEYBOARD_ASSET then KEYBOARD_ASSET = ensureAsset(KEYBOARD_PATH, KEYBOARD_B64) end
        return KEYBOARD_ASSET
    elseif id == "custom:space" then
        if not SPACE_ASSET then SPACE_ASSET = ensureAsset(SPACE_PATH, SPACE_B64) end
        return SPACE_ASSET
    end
    return id
end

local function attachSeamlessLoop(s, gen)
    s.Ended:Connect(function()
        if not soundKeepAlive or gen ~= soundGeneration then return end
        pcall(function()
            s.TimePosition = 0
            s:Play()
        end)
    end)
end

local function getSoundFolder()
    local pg = LocalPlayer:FindFirstChild("PlayerGui")
    if pg then
        local folder = pg:FindFirstChild("BanwareSounds")
        if not folder then
            folder = Instance.new("Folder")
            folder.Name = "BanwareSounds"
            folder.Parent = pg
        end
        return folder
    end
    return SoundService
end

local function spawnLayer(id, speed, volMul, gen)
    local s = Instance.new("Sound")
    s.Name = "BanwareSFX"
    s.SoundId = id
    s.Volume = math.clamp(soundCFG.VOLUME * (volMul or 1), 0, 10)
    s.Looped = true
    s.PlaybackSpeed = speed or 1
    s.PlayOnRemove = false
    s.Parent = getSoundFolder()
    attachSeamlessLoop(s, gen)

    -- Play + local play for max compatibility
    pcall(function() s:Play() end)
    pcall(function() SoundService:PlayLocalSound(s) end)

    -- Keep forcing play for a short window until it actually starts
    task.spawn(function()
        for _ = 1, 20 do
            if not soundKeepAlive or gen ~= soundGeneration then return end
            if s.IsPlaying then return end
            pcall(function()
                s:Play()
                SoundService:PlayLocalSound(s)
            end)
            task.wait(0.1)
        end
    end)

    table.insert(activeSounds, s)
    return s
end

function startVoidSound()
    clearSounds()
    local name = soundCFG.ENABLED_NAME
    if not name or name == "None" then return end

    local id = resolveSoundId(name)
    if not id then
        Library:Notify("Sound not ready (need getcustomasset/writefile)", 3)
        return
    end

    soundKeepAlive = true
    local gen = soundGeneration

    -- Custom full tracks: single clean loop (no pitch layers)
    if name == "Keyboard" or name == "Space" then
        spawnLayer(id, 1.0, 1.0, gen)
    elseif name == "Drone" or name == "Ambient" then
        spawnLayer(id, 0.55, 1.2, gen)
        spawnLayer(id, 0.85, 0.7, gen)
        spawnLayer(id, 1.15, 0.4, gen)
    elseif name == "Bass" or name == "Hum" then
        spawnLayer(id, 0.4, 1.4, gen)
        spawnLayer(id, 0.65, 0.9, gen)
    elseif name == "Whoosh" or name == "Rush" then
        spawnLayer(id, 0.7, 1.1, gen)
        spawnLayer(id, 1.0, 0.8, gen)
    elseif name == "Glitch" or name == "Static" or name == "Pulse" then
        spawnLayer(id, 0.9, 1.0, gen)
        spawnLayer(id, 1.2, 0.6, gen)
    else
        spawnLayer(id, 1.0, 1.0, gen)
    end

    soundLoopConn = RunService.Heartbeat:Connect(function()
        if not soundKeepAlive or gen ~= soundGeneration or not voidEnabled then
            return
        end
        for _, s in ipairs(activeSounds) do
            if s and s.Parent and not s.IsPlaying then
                pcall(function()
                    s.TimePosition = 0
                    s:Play()
                end)
            end
        end
    end)
end


function playDisableSound()
    if not DISABLE_ASSET then
        DISABLE_ASSET = ensureAsset(DISABLE_PATH, DISABLE_B64)
    end
    if not DISABLE_ASSET then return end
    local s = Instance.new("Sound")
    s.Name = "BanwareVoidDisable"
    s.SoundId = DISABLE_ASSET
    s.Volume = math.clamp(soundCFG.VOLUME, 0, 10)
    s.Looped = false
    s.Parent = getSoundFolder()
    pcall(function() s:Play() end)
    pcall(function() SoundService:PlayLocalSound(s) end)
    s.Ended:Connect(function()
        pcall(function() s:Destroy() end)
    end)
    task.delay(6, function()
        pcall(function() if s and s.Parent then s:Destroy() end end)
    end)
end

function stopVoidSound()
    clearSounds()
end

local testToken = 0
function testVoidSound()
    -- hard stop everything first (no overlap)
    stopVoidSound()
    testToken = testToken + 1
    local myToken = testToken
    local myGen = soundGeneration

    if soundCFG.ENABLED_NAME == "None" then
        Library:Notify("Pick a sound first", 2)
        return
    end

    startVoidSound()
    Library:Notify("Preview 3s: " .. tostring(soundCFG.ENABLED_NAME), 1.5)

    task.delay(3, function()
        -- only the latest test may stop itself; ignore stale timers
        if myToken ~= testToken then return end
        stopVoidSound()
        -- resume void loop only if void hide is on
        if voidEnabled and soundCFG.ENABLED_NAME ~= "None" then
            startVoidSound()
        end
    end)
end

