    Placeholder = 'config name',
})

ConfigBox:AddButton('Save Config', function()
    local name = 'default'
    pcall(function()
        name = tostring(Options.ConfigNameInput.Value or 'default'):gsub('%s+', '_')
    end)
    if name == '' then name = 'default' end
    local ok = pcall(function() SaveManager:Save(name) end)
    if ok then
        Library:Notify('Saved: ' .. name, 2)
        pcall(function() SaveManager:RefreshConfigList() end)
    else
        Library:Notify('Save failed', 3)
    end
end)

ConfigBox:AddButton('Load Config', function()
    local name = 'default'
    pcall(function()
        name = tostring(Options.ConfigNameInput.Value or 'default'):gsub('%s+', '_')
    end)
    local ok = pcall(function() SaveManager:Load(name) end)
    Library:Notify(ok and ('Loaded: ' .. name) or 'Load failed', 2)
end)

ConfigBox:AddButton('Delete Config', function()
    local name = 'default'
    pcall(function()
        name = tostring(Options.ConfigNameInput.Value or 'default'):gsub('%s+', '_')
    end)
    pcall(function()
        if SaveManager.Delete then SaveManager:Delete(name)
        elseif delfile and isfile then
            local path = 'Banware/configs/' .. name .. '.json'
            if isfile(path) then delfile(path) end
        end
    end)
    Library:Notify('Deleted: ' .. name, 2)
end)

pcall(function() SaveManager:BuildConfigSection(Tabs.Settings) end)
pcall(function() ThemeManager:ApplyToTab(Tabs.Settings) end)

