local function MakeMobileButton(name, text, y)
    local btn = Instance.new("TextButton")
    btn.Name = name
    btn.Size = UDim2.fromOffset(isMobile and 95 or 105, isMobile and 34 or 32)
    btn.Position = UDim2.fromOffset(0, y)
    btn.BackgroundColor3 = Color3.fromRGB(15, 20, 15)
    btn.BorderSizePixel = 0
    btn.Text = text
    btn.TextColor3 = Color3.fromRGB(230, 230, 235)
    btn.TextSize = isMobile and 14 or 12
    btn.Font = Enum.Font.GothamMedium
    btn.AutoButtonColor = false
    btn.Parent = ButtonHolder

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = btn

    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(200, 200, 210)
    stroke.Thickness = 1.2
    stroke.Parent = btn

    local function press()
        TweenService:Create(btn, TweenInfo.new(0.08), {BackgroundColor3 = Color3.fromRGB(60, 60, 70)}):Play()
    end
    local function release()
        TweenService:Create(btn, TweenInfo.new(0.1), {BackgroundColor3 = Color3.fromRGB(15, 20, 15)}):Play()
    end
    btn.MouseButton1Down:Connect(press)
    btn.MouseButton1Up:Connect(release)
    btn.MouseLeave:Connect(release)
    return btn
end

local ToggleBtn = MakeMobileButton("ToggleUI", "Toggle UI", 0)
local LockBtn = MakeMobileButton("LockUI", "Unlock UI", 40)

local menuVisible = true
local uiLocked = false

ToggleBtn.MouseButton1Click:Connect(function()
    menuVisible = not menuVisible
