local hudDrag = false
local hudOrigin = Vector2.zero
local hudStart = Vector2.zero

hud.InputBegan:Connect(function(inp)
    if inp.UserInputType == Enum.UserInputType.MouseButton1 then
        hudDrag = true; hudOrigin = inp.Position; hudStart = hud.Position
    end
end)
hud.InputEnded:Connect(function(inp)
    if inp.UserInputType == Enum.UserInputType.MouseButton1 then hudDrag = false end
end)
UIS.InputChanged:Connect(function(inp)
    if hudDrag and inp.UserInputType == Enum.UserInputType.MouseMovement then
        local d = inp.Position - hudOrigin
        hud.Position = UDim2.new(hudStart.X.Scale, hudStart.X.Offset + d.X, hudStart.Y.Scale, hudStart.Y.Offset + d.Y)
    end
end)

local function fmt(n)
    local a = math.abs(n)
    if a >= 1e9 then
        return string.format("%.2fB", n / 1e9)
    elseif a >= 1e6 then
        return string.format("%.2fM", n / 1e6)
    elseif a >= 1e4 then
        return string.format("%.1fK", n / 1e3)
    elseif a >= 100 then
        return string.format("%.1f", n)
    else
        return string.format("%.2f", n)
    end
end

local hudT = 0
RunService.Heartbeat:Connect(function(dt)
    if not studGui.Enabled then return end
    hudT = hudT + dt * 3
    local p = (math.sin(hudT) + 1) * 0.5
    liveDot.BackgroundColor3 = Color3.fromRGB(
        math.floor(120 + p * 50),
        math.floor(70 + p * 50),
        math.floor(220 + p * 30)
    )

    local c = LP.Character
    local hrp = c and c:FindFirstChild("HumanoidRootPart")
    if hrp then
        local pos = hrp.Position
        axisVals.X.Text = fmt(pos.X)
        axisVals.Y.Text = fmt(pos.Y)
        axisVals.Z.Text = fmt(pos.Z)

        local nx = math.clamp(math.abs(pos.X) / 10000, 0, 1)
        local ny = math.clamp(math.abs(pos.Y) / 10000, 0, 1)
        local nz = math.clamp(math.abs(pos.Z) / 10000, 0, 1)
        axisBars.X.Size = UDim2.new(nx, 0, 1, 0)
        axisBars.Y.Size = UDim2.new(ny, 0, 1, 0)
        axisBars.Z.Size = UDim2.new(nz, 0, 1, 0)
    else
        axisVals.X.Text = "--"
        axisVals.Y.Text = "--"
        axisVals.Z.Text = "--"
        axisBars.X.Size = UDim2.new(0, 0, 1, 0)
        axisBars.Y.Size = UDim2.new(0, 0, 1, 0)
        axisBars.Z.Size = UDim2.new(0, 0, 1, 0)
    end
end)

